## useEffect e o array de dependências

```tsx
useEffect(() => {
  localStorage.setItem("tasks", JSON.stringify(tasks));
}, [tasks]);
```

O segundo argumento é **o que o sensor vigia**:

- `[tasks]` → roda no primeiro desenho e **de novo sempre que `tasks` mudar**
- `[]` → roda **uma vez só**, depois do primeiro desenho
- sem array → roda depois de **todo** desenho (quase nunca é o que você quer)

> Esqueceu uma variável que o efeito usa? Ele roda com o valor velho. Colocou coisa demais? Roda à toa.

spec.starter:
// useState e useEffect já estão disponíveis — não precisa importar.
// O preview não tem localStorage: esta gaveta de mentira faz o papel dele.
const gaveta: Record<string, string> = {};

function carregar(): string[] {
  const salvo = gaveta["tasks"];
  return salvo ? JSON.parse(salvo) : ["Estudar React", "Beber água"];
}

export default function App() {
  const [tasks, setTasks] = useState<string[]>(carregar);
  const [text, setText] = useState("");

  // o efeito que salva entra aqui

  function addTask() {
    if (text.trim() === "") return;
    setTasks([...tasks, text]);
    setText("");
  }

  return (
    <div className="p-4">
      <input id="nova" className="border px-2" value={text} onChange={(e) => setText(e.target.value)} />
      <button onClick={addTask}>Adicionar</button>
      <ul>
        {tasks.map((task) => (
          <li key={task}>{task}</li>
        ))}
      </ul>
    </div>
  );
}

