const TAREFAS = ["Estudar React", "Beber água", "Ler um capítulo"];

// O preview não acessa a internet: esta função finge o fetch do tarefas.json.
function buscarTarefas(falhar: boolean): Promise<string[]> {
  return falhar ? Promise.reject(new Error("HTTP 500")) : Promise.resolve(TAREFAS);
}

export default function App() {
  const [tasks, setTasks] = useState<string[]>([]);
  const [status, setStatus] = useState<"carregando" | "pronto" | "erro">("carregando");
  const [falhar, setFalhar] = useState(false);

  // o efeito que busca entra aqui

  return (
    <div className="p-4">
      <button onClick={() => { setStatus("carregando"); setFalhar(true); }}>Simular erro</button>
      {status === "carregando" && <p data-carregando>Carregando tarefas…</p>}
      {status === "erro" && <p data-erro>Não deu pra carregar. Tente de novo.</p>}
      {status === "pronto" && (
        <ul>
          {tasks.map((task) => (
            <li key={task}>{task}</li>
          ))}
        </ul>
      )}
    </div>
  );
}

